const { env } = await import('node:process');
if (!env.INPUT_PATH) throw new Error('Missing INPUT_PATH');
if (!env.OUTPUT_PATH) throw new Error('Missing OUTPUT_PATH');
globalThis.inputPath = env.INPUT_PATH;
globalThis.outputPath = env.OUTPUT_PATH;
globalThis.resize = env.RESIZE || null;
globalThis.quality = env.QUALITY !== undefined ? Number(env.QUALITY) : null;

const { createReadStream, createWriteStream } = await import('node:fs');
const imMod = await import('imagemagick-stream');
const im = imMod.default || imMod;
let stream = im();
if (globalThis.resize) stream = stream.resize(globalThis.resize);
if (globalThis.quality !== null) stream = stream.quality(globalThis.quality);
const read = createReadStream(globalThis.inputPath);
const write = createWriteStream(globalThis.outputPath);
await new Promise((resolve, reject) => {
  read.pipe(stream).pipe(write);
  write.on('finish', resolve);
  write.on('error', reject);
  stream.on('error', reject);
});
